-- A "Word to know" card for every game page. Run once in the Supabase SQL Editor (safe to run again). Only adds the four vocab fields; nothing else on a game changes.
with w(id, patch) as (values
  ('game-pathbuilder', $j${"vocabWord":"engineer","vocabSay":"en-jin-EER · noun","vocabMeaning":"Someone who plans and builds things like roads, bridges and machines, and fixes the problems along the way.","vocabExample":"In Pathbuilder you are the engineer! Plan the shortest road, build a bridge over the river, and fix your plan if it does not work."}$j$::jsonb),
  ('game-gravity-four', $j${"vocabWord":"gravity","vocabSay":"GRAV-ih-tee · noun","vocabMeaning":"The invisible pull that brings things down to the ground.","vocabExample":"In Chike’s Gravity 4, gravity pulls your chip down to the lowest empty spot in the column!"}$j$::jsonb),
  ('game-doodle-dash', $j${"vocabWord":"design","vocabSay":"dih-ZINE · noun","vocabMeaning":"A plan for how something will look and work before you make it.","vocabExample":"In Doodle Dash you design a level with markers or crayons, then run through your own design."}$j$::jsonb),
  ('game-ufo', $j${"vocabWord":"efficiency","vocabSay":"ih-FISH-un-see · noun","vocabMeaning":"Getting a lot done without wasting effort, like using each shot well.","vocabExample":"In Cosmic Blast!, every shot that hits raises your efficiency score. Aim before you fire!"}$j$::jsonb),
  ('game-air-hockey', $j${"vocabWord":"sum","vocabSay":"SUM · noun","vocabMeaning":"The answer you get when you add numbers together.","vocabExample":"In Air Hockey Arcade, add up the numbers on the pucks you score. The first sum to reach 25 wins."}$j$::jsonb),
  ('game-bounce-and-bank', $j${"vocabWord":"probability","vocabSay":"prob-uh-BIL-ih-tee · noun","vocabMeaning":"How likely it is that something will happen.","vocabExample":"In Bounce & Bank, a ball is more likely to land in some slots than in others. That is probability at work!"}$j$::jsonb),
  ('game-spacetime', $j${"vocabWord":"orbit","vocabSay":"OR-bit · noun","vocabMeaning":"The curved path a planet takes around the Sun.","vocabExample":"Use Warp Orbits in the Solar System Sandbox to move a planet, then watch how its orbit changes."}$j$::jsonb),
  ('game-balloon-math', $j${"vocabWord":"place value","vocabSay":"PLAYSS VAL-yoo · noun","vocabMeaning":"What a digit is worth depends on where it sits in a number. In 42, the 4 means four tens.","vocabExample":"Pop the right balloon when Balloon Pop Math asks about tens and ones."}$j$::jsonb),
  ('game-drop-blox', $j${"vocabWord":"pattern","vocabSay":"PAT-ern · noun","vocabMeaning":"Something that repeats in an order you can spot and predict.","vocabExample":"In DropBlox, look for colours that make a pattern, then line up six in a row to clear them."}$j$::jsonb),
  ('game-maze', $j${"vocabWord":"strategy","vocabSay":"STRAT-uh-jee · noun","vocabMeaning":"A plan for getting where you want to go.","vocabExample":"In Maze Quest, look ahead before you walk. Which turn gets you out fastest? That is a strategy."}$j$::jsonb),
  ('game-memory', $j${"vocabWord":"memory","vocabSay":"MEM-uh-ree · noun","vocabMeaning":"How your brain keeps things you have seen so you can find them again.","vocabExample":"In Memory Match, picture where each shape is hiding, then say it out loud to help it stick."}$j$::jsonb),
  ('game-spelling', $j${"vocabWord":"clue","vocabSay":"KLOO · noun","vocabMeaning":"A hint that helps you work something out.","vocabExample":"In Spelling Detective, read the clue first, then solve the word one letter at a time."}$j$::jsonb),
  ('game-materials-mashup', $j${"vocabWord":"invention","vocabSay":"in-VEN-shun · noun","vocabMeaning":"A brand new thing that someone thinks up and makes.","vocabExample":"Grab three things and ask: what new invention could they become together?"}$j$::jsonb),
  ('game-draw-what-i-say', $j${"vocabWord":"describe","vocabSay":"dih-SKRIBE · verb","vocabMeaning":"To use words so that someone else can picture something.","vocabExample":"In Draw What I Say, describe your picture with shapes and places, like “a circle in the top corner”."}$j$::jsonb),
  ('game-sound-hunt', $j${"vocabWord":"vibration","vocabSay":"vy-BRAY-shun · noun","vocabMeaning":"A very fast shake back and forth. Vibrations make sounds.","vocabExample":"Tap a spoon on a cup and touch the cup lightly. Can you feel the vibration?"}$j$::jsonb),
  ('game-bridge-challenge', $j${"vocabWord":"load","vocabSay":"LOHD · noun","vocabMeaning":"The weight that a bridge or building has to hold up.","vocabExample":"In The Bridge Challenge, every coin adds to the load. How many can your paper bridge hold?"}$j$::jsonb),
  ('game-story-relay', $j${"vocabWord":"narrator","vocabSay":"NAIR-ay-ter · noun","vocabMeaning":"The person who tells a story.","vocabExample":"In Story Relay, everyone takes a turn as the narrator by adding one sentence."}$j$::jsonb),
  ('game-freeze-swap', $j${"vocabWord":"transform","vocabSay":"trans-FORM · verb","vocabMeaning":"To change into something different.","vocabExample":"When the music stops in Freeze and Swap, transform into a new animal, machine or character."}$j$::jsonb)
)
update games g set data = g.data || w.patch, updated_at = now() from w where g.id = w.id;
